transforms.code:
''' Gets the tag values for the selected paths '''

tagPaths = self.custom.data.tagPaths
infeedPath = tagPaths.get('infeedPath')
outfeedPath = tagPaths.get('outfeedPath')
rejectPath = tagPaths.get('rejectPath')
modePath = tagPaths.get('modePath')
statePath = tagPaths.get('statePath')

# Reads the tag values if a mapping has been selected
if infeedPath not in [None, '']:
	infeedValue = system.tag.readBlocking([infeedPath])[0].value
else:
	infeedValue = ''

if outfeedPath not in [None, '']:
	outfeedValue = system.tag.readBlocking([outfeedPath])[0].value
else:
	outfeedValue = ''

if rejectPath not in [None, '']:
	rejectValue = system.tag.readBlocking([rejectPath])[0].value
else:
	rejectValue = ''

if modePath not in [None, '']:
	modeValue = system.tag.readBlocking([modePath])[0].value
else:
	modeValue = ''

if statePath not in [None, '']:
	stateValue = system.tag.readBlocking([statePath])[0].value
else:
	stateValue = ''

# Returns the tagValues dict
tagValues = {
	'infeedValue': infeedValue,
	'outfeedValue': outfeedValue,
	'rejectValue': rejectValue,
	'modeValue': modeValue,
	'stateValue': stateValue
}
return tagValues

